script:
frappe.ui.form.on("Murasalat Correspondence", {
    onload(frm) {
        if (!frm.is_new() || frm.doc.current_department) {
            return;
        }

        frappe.db
            .get_value(
                "Employee",
                { user_id: frappe.session.user },
                "department"
            )
            .then(({ message }) => {
                if (message?.department) {
                    frm.set_value(
                        "current_department",
                        message.department
                    );
                }
            });
    }
});
